<?= $this->extend('admin/layouts/main') ?><?= $this->section('content') ?><div class="d-flex justify-content-between mb-3"><h1 class="h3">Guides</h1><a class="btn btn-success" href="<?= url_to('admin.guides.create') ?>">New guide</a></div><form class="row g-2 mb-3"><div class="col-md-5"><input class="form-control" name="q" value="<?= esc($q,'attr') ?>" placeholder="Search"></div><div class="col-md-3"><select class="form-select" name="status"><option value="">All statuses</option><?php foreach(['draft','published','scheduled'] as $s): ?><option value="<?= $s ?>" <?= $status===$s?'selected':'' ?>><?= ucfirst($s) ?></option><?php endforeach ?></select></div><div class="col-md-3"><select class="form-select" name="category_id"><option value="">All categories</option><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= $category==(int)$c['id']?'selected':'' ?>><?= esc($c['name']) ?></option><?php endforeach ?></select></div><div class="col-md-1"><button class="btn btn-outline-success">Filter</button></div></form><div class="table-responsive"><table class="table table-striped"><thead><tr><th>Title</th><th>Status</th><th>Published</th><th>Views</th><th></th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= esc($row['title']) ?></td><td><?= esc($row['status']) ?></td><td><?= esc($row['published_at']??'') ?></td><td><?= (int)$row['views'] ?></td><td><a href="<?= url_to('admin.guides.edit',$row['id']) ?>">Edit</a> <form class="d-inline" method="post" action="<?= site_url('admin/guides/'.$row['id'].'/delete') ?>" onsubmit="return confirm('Delete guide?')"><?= csrf_field() ?><button class="btn btn-link text-danger p-0">Delete</button></form></td></tr><?php endforeach ?></tbody></table></div><?= $pager->links() ?><?= $this->endSection() ?>
